// === Uncler M Variant #3: Synthwave Wireframe Sphere & Frequency Lattice ===
// Inspired by OpenProcessing 2955184 'Unusual Globe' by u110137

const num = 180;
let counter = 0;
let mode = 2;
let ang, tang;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	colorMode(HSB, 360, 100, 100, 100);
	ang = createVector(0, 0, 0);
	tang = createVector(HALF_PI, 0, 0);
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

function draw() {
	let bEnergy = (window.beatEnergy || 0.0);
	let bassE = (window.bassEnergy || 0.0);
	let midE = (window.midEnergy || 0.0);
	let highE = (window.highEnergy || 0.0);

	counter += (1.5 + highE * 3.5);
	tang.y = sin(frameCount * 0.02) * 1.6;
	tang.x = cos(frameCount * 0.015) * 1.6;
	ang.lerp(tang, 0.07);

	let m = 6 * TAU * cos(counter / 180) / num;
	orbitControl(0, 0, 0.5);
	rotateZ(ang.z);
	rotateY(ang.y);
	rotateX(ang.x + frameCount * 0.01);
	background(280, 90, 8);
	noFill();

	for (let i = 0; i < min(num, frameCount); i++) {
		let a = i * PI / num;
		let r = sin(a) * min(width, height) / 2.2;

		// Synthwave Magenta & Cyan HSL Palette
		let hueVal = (300 + i * 0.6 + highE * 50) % 360;
		let satVal = 85 + cos(i * 0.1) * 15;
		let briVal = 80 + bEnergy * 20;
		stroke(hueVal, satVal, briVal, 80);
		strokeWeight(1.2 + (i % 2 === 0 ? 1.8 : 0) + midE * 2.0);

		push();
		switch (mode) {
			case 0:
				rotateZ(2 * (i - num / 2) * m);
				break;
			case 1:
				rotateZ((i < num / 2) * PI);
				rotateY((i - num / 2) * m);
				break;
			case 2:
				rotateZ((i < num / 2) * PI);
				rotateX((i - num / 2) * m);
				break;
		}
		translate(0, 0, cos(a) * min(width, height) / 2.5);
		arc(0, 0, r, r, 0, PI, OPEN, 36);
		pop();
	}
}

if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
